# --- Intent ----------
idan:R1_PSE_Res_Slice_Intent1
 a icm:Intent ;
   rdfs:comment "'Intent for ordering connectivity via slice'";
   imo:intentOwner idan:IntentManagerXYZ_S;
   cem:layer "'resource'";
   icm:hasExpectation idan:PSE_Exp_R1Slice_delivery,
                         idan:PSE_Exp_R1Slice_property,
                         idan:PSE_Exp_R1Slice_reporting; 
.
##Delivery Expectation
idan:PSE_Exp_R1Slice_delivery
 a icm:DeliveryExpectation ;
   icm:target _:resource_slice ;
   icm:params idan:PSE_Exp_R1Slice_delivery_Param_type;
.
idan:PSE_Exp_R1Slice_delivery_Param_type
 a icm:DeliveryParam ;
   icm:targetDescription cat:Slice_NEST_eMBB;
.

##Property Expectation
idan:PSE_Exp_R1Slice_property
 a icm:PropertyExpectation ;
   icm:target _:resource_slice ;
   icm:params idan:PSE_Exp_R1Slice_property_Param_nssiId , 
               idan:PSE_Exp_R1Slice_property_Param_nssiName , 
               idan:PSE_Exp_R1Slice_property_Param_nsiId , 
               idan:PSE_Exp_R1Slice_property_Param_latency

.
idan:PSE_Exp_R1Slice_property_Param_nssiId
 a icm:PropertyParam ;
   sli:nssiId [ icm:value "'NEST-EMBB_VIDEOSTREAMING_INSIDE_VENUE_5G'"^^xsd:string ] ;
.
idan:PSE_Exp_R1Slice_property_Param_nssiName
 a icm:PropertyParam ;
   sli:nssiName [ icm:value "'NEST-EMBB_VIDEOSTREAMING_INSIDE_VENUE_5G'"^^xsd:string ] ;
.
idan:PSE_Exp_R1Slice_property_Param_nsiId
 a icm:PropertyParam ;
   sli:nsiId [ icm:value "'NEST-EMBB_VIDEOSTREAMING_INSIDE_VENUE_5G'"^^xsd:string ] ;
.
idan:PSE_Exp_R1Slice_property_Param_latency
 a icm:PropertyParam ;
   met:latency [ icm:atMost "'12 ms'" ] ;
.

##Reporting Expectation
idan:PSE_Exp_R1Slice_reporting
 a icm:ReportingExpectation ;
   icm:target idan:R1_PSE_Res_Slice_Intent1 ;
   icm:params idan:PSE_Exp_R1Slice_reporting_Param_interval,
               idan:PSE_Exp_R1Slice_reporting_Param_event ;
.
idan:PSE_Exp_R1Slice_reporting_Param_interval
 a icm:ReportingParam ;
   icm:reportingInterval [ a t:Duration ;
                                t:numericDuration "'10'" ;
                                t:temporalUnit t:unitMinute ] .
idan:PSE_Exp_R1Slice_reporting_Param_event              
 a icm:ReportingParam ; 
   icm:reportingEvent icm:ReportingIntervalExpired ,
                        icm:IntentRejected ,
                        icm:StateComplies ,
                        icm:StateDegrades ,
                        icm:HandlingEnded ,
                        icm:UpdateRejected ,
                        icm:UpdateFinished  ;
.

